import sys

MOD = 1_000_000_007

def solve(raw):
    data = list(map(int, raw.split()))
    n, left, right = data[:3]
    values = data[3:]
    counts = [0] * (n + 1)
    for value in values:
        if value <= n:
            counts[value] += 1
    powers = [1] * (n + 1)
    for i in range(1, n + 1):
        powers[i] = powers[i - 1] * 2 % MOD

    answer = prefix = 0
    product = 1
    remaining = n
    for mex in range(min(n, right) + 1):
        count = counts[mex]
        remaining -= count
        if mex >= left:
            answer = (answer + product * powers[remaining]) % MOD
        product = product * (powers[count] - 1) % MOD
    return str(answer)

if __name__ == "__main__":
    print(solve(sys.stdin.read()))

import sys

MONTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
PREFIX = (0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334)

def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def ordinal(year, month, day):
    previous = year - 1
    total = 365 * previous + previous // 4 - previous // 100 + previous // 400
    total += PREFIX[month - 1]
    if month > 2 and is_leap(year):
        total += 1
    return total + day - 1

def solve(raw):
    y1, m1, d1, y2, m2, d2 = map(int, raw.split())
    return str(ordinal(y2, m2, d2) - ordinal(y1, m1, d1))

if __name__ == "__main__":
    print(solve(sys.stdin.read()))
